 @Test void explicitSelectedAvailablePairsCanBeConfirmed(){service.validateConfirmation(row(ready()));noProductWrites();}
 @Test void unavailableAndUnverifiedSelectedPairsCannotBeConfirmed(){for(String state:List.of("unavailable","unverified")){var input=ready();var fact=new LinkedHashMap<>(maps(input.get("pairings")).get(0));fact.put("state",state);input.put("pairings",List.of(fact));assertThrows(BusinessException.class,()->service.validateConfirmation(row(input)));}noProductWrites();}
 @Test void twoResolvedRangesNeverInventCartesianSupply(){var input=ready();input.put("selectedPairs",List.of(Map.of("phoneModelId",12L,"colorId",3L),Map.of("phoneModelId",12L,"colorId",4L)));assertThrows(BusinessException.class,()->service.validateConfirmation(row(input)));}
 @Test void phoneChoiceAndPairChoiceMustAgree(){var input=ready();input.put("phoneModelIds",List.of(13));assertThrows(BusinessException.class,()->service.validateConfirmation(row(input)));}
 @Test void crossSupplierFactsAreNotCopiedAsNewSupplierTruth(){var input=ready();input.put("supplierCode","S2");assertThrows(BusinessException.class,()->service.validateConfirmation(row(input)));}
 @Test void rangeResolutionFailureRemainsVisibleDraftAndBlocksConfirmation(){when(ranges.resolveReferences(anyString(),anyList(),anyString(),anyString(),anyBoolean())).thenThrow(new BusinessException(40001,"范围重名待核对"));var r=row(ready());assertEquals(List.of("范围重名待核对"),r.get("rangeIssues"));assertThrows(BusinessException.class,()->service.validateConfirmation(r));}
 @Test void frozenRowsPreserveOldEvidenceAndDoNotRefreshPhoneNames(){var frozen=row(ready());frozen.put("confirmed",true);frozen.put("confirmedAt","2026-10-21T12:00:00Z");clearInvocations(products);assertEquals(signature(store.json,frozen),signature(store.json,service.canonicalRow(9,frozen,values("rowId",frozen.get("rowId")))));verifyNoInteractions(products);assertThrows(BusinessException.class,()->service.canonicalRow(9,frozen,values("rowId",frozen.get("rowId"),"discarded",true)));}
 @Test void currencyBusinessDefaultNeverGrantsFinanceWrite(){var r=ready();r.put("unitPrice","12");var draft=row(r);assertEquals("CNY",draft.get("currency"));service.validateConfirmation(draft);noProductWrites();}
 @Test void moneyDoesNotRoundAndSelectionMarkersMustBeBoolean(){assertThrows(BusinessException.class,()->row(values("unitPrice","1.001")));assertThrows(BusinessException.class,()->row(values("unitPrice","-1")));assertThrows(BusinessException.class,()->row(values("selected","是")));assertEquals("0.00",row(values("unitPrice","0")).get("unitPrice"));}
 @Test void readonlyViewRedactsEverySnapshotDepth(){when(permissions.costs()).thenReturn(false);Map<String,Object> d=values("name","可读款","unitPrice","12","currency","USD","confirmationSnapshot",Map.of("source",Map.of("priceCents",1200,"terms","供方条款")));Map<String,Object> visible=ReflectionTestUtils.invokeMethod(service,"visible",d);assertEquals("可读款",visible.get("name"));assertFalse(visible.containsKey("unitPrice"));assertEquals(Map.of("source",Map.of()),visible.get("confirmationSnapshot"));}
 @Test void engineeringGuardRunsBeforeRecordWrites(){doThrow(new BusinessException(40103,"仅国内工程可维护")).when(permissions).engineer();assertThrows(BusinessException.class,()->service.save(null,values("requestId","denied")));assertThrows(BusinessException.class,()->service.patchRows(9,values("requestId","denied")));assertThrows(BusinessException.class,()->service.confirm(9,values("requestId","denied")));verify(store,never()).load(anyLong(),anyString(),anyBoolean());noProductWrites();}
 @Test void sourceTextAutomaticallyReusesRealPhonesWithoutProductOrCodeCreation(){var resolver=mock(PartnerCatalogPhoneResolver.class);var scope=mock(PartnerCatalogPhoneResolver.ResolutionScope.class);ReflectionTestUtils.setField(service,"phoneResolver",resolver);when(resolver.newScope()).thenReturn(scope);when(scope.resolve(anyMap())).thenAnswer(i->{var r=new LinkedHashMap<String,Object>(i.getArgument(0));r.put("phoneModelIds",List.of(18L,11L));r.put("phoneMatchIssues",List.of());r.put("phoneMatchSummary",Map.of("matchedCount",2));return r;});var r=row(values("modelText","iPhone11到18"));assertEquals(List.of(18L,11L),r.get("phoneModelIds"));verify(products).selectedPhones(List.of(18L,11L),List.of());verify(resolver,times(1)).newScope();noProductWrites();}
 @Test void explicitPhoneIdentityIsNotReplacedBySourceText(){var resolver=mock(PartnerCatalogPhoneResolver.class);ReflectionTestUtils.setField(service,"phoneResolver",resolver);var r=row(values("modelText","iPhone11到18","phoneModelIds",List.of(12L)));assertEquals(List.of(12L),r.get("phoneModelIds"));verifyNoInteractions(resolver);}
 @Test void catalogOriginIsImmutableAndAllLaterRowChangesStayInsideTheFrozenSupplierScope(){
  var original=row(ready());original.put("catalogSourceSnapshot",values("sourceKind","selection","recordId",8L,"supplierCode","S1","phoneModelIds",List.of(12L,13L),"unavailablePhoneModelIds",List.of(13L)));
  var ok=service.canonicalRow(9,original,values("rowId",original.get("rowId"),"notes","人工备注"));assertEquals("人工备注",ok.get("notes"));assertEquals(original.get("catalogSourceSnapshot"),ok.get("catalogSourceSnapshot"));
  for(var changes:List.of(values("phoneModelIds",List.of(99L)),values("phoneModelIds",List.of()),values("phoneModelIds",List.of(13L)),values("supplierCode","S2"),values("catalogSourceSnapshot",Map.of()),values("catalogSourceSnapshot",values("phoneModelIds",List.of(99L))))){changes.put("rowId",original.get("rowId"));assertThrows(BusinessException.class,()->service.canonicalRow(9,original,changes));}noProductWrites();
 }
