 @Test void markedLegacySourceRejectsOrdinarySelectionWritesBeforeAnyAuditOrProductMutation(){
  doReturn(values("id",9L,"name","原资料","version",4L,"catalogSource",true)).when(store).load(9L,"selection",true);
  doReturn(values("id",9L,"name","原资料","version",4L,"catalogSource",true)).when(store).load(9L,"selection",false);
  var command=values("requestId","must-not-write","version",4L,"operations",List.of());
  assertThrows(BusinessException.class,()->service.save(9L,command));assertThrows(BusinessException.class,()->service.patchRows(9L,command));assertThrows(BusinessException.class,()->service.batch(9L,command));assertThrows(BusinessException.class,()->service.applyImportedRows(9L,4L,"import",List.of()));assertThrows(BusinessException.class,()->service.confirmationPreview(9L,command));assertThrows(BusinessException.class,()->service.confirm(9L,command));
  verify(store,never()).save(anyLong(),anyMap());verify(store,never()).revision(anyLong(),anyMap());verify(store,never()).event(anyLong(),anyString(),anyMap(),anyString());noProductWrites();
 }
 @Test void legacySourceDetailRemainsReadableAtItsOriginalUrlButIsNeverEditable(){
  doReturn(values("id",9L,"name","真实旧资料","version",5L,"supplierCode","S1","catalogSource",true)).when(store).load(9L,"selection",false);
  when(jdbc.queryForMap(contains("count(*) as \"rowCount\""),eq(9L))).thenReturn(values("rowCount",19L,"confirmedCount",0L,"finishedCount",0L));when(jdbc.queryForObject(anyString(),eq(Long.class),any(Object[].class))).thenReturn(0L);
  var detail=service.detail(9L);assertEquals(9L,detail.get("id"));assertEquals(5L,detail.get("version"));assertEquals("catalog_source",detail.get("purpose"));assertEquals(false,detail.get("canWrite"));assertThrows(BusinessException.class,()->service.pageRows(9L,Map.of()));noProductWrites();
 }
