 @Test void labeledPriceOptionsAndThicknessKeepTheirMeaning(){var r=row(values("thickness","亚克力1.5mm TPU厚2mm","features","磁吸支架","priceOptions",List.of(values("label","裸壳","unitPrice","2.4","priceNote","原文2.4元","untrusted","discard"),values("label","OPP包装加价","unitPrice","0.1"))));var options=maps(r.get("priceOptions"));assertEquals(2,options.size());assertEquals("2.40",options.get(0).get("unitPrice"));assertEquals("CNY",options.get(0).get("currency"));assertEquals("business_default",options.get(0).get("currencySource"));assertFalse(options.get(0).containsKey("untrusted"));assertEquals("亚克力1.5mm TPU厚2mm",r.get("thickness"));assertThrows(BusinessException.class,()->row(values("priceOptions",List.of(values("unitPrice","2.4")))));assertThrows(BusinessException.class,()->row(values("priceOptions",List.of(values("label","裸壳","unitPrice","2.401")))));}
